mapper.select:
SELECT r.id, r.receipt_no,
r.purchase_order_id,
r.purchase_order_no_snapshot AS purchase_order_no,
r.supplier_id,
r.supplier_name_snapshot AS supplier_name,
r.warehouse_id,
r.warehouse_name_snapshot AS warehouse_name,
r.status, r.receipt_mode, r.putaway_status, r.putaway_at, r.putaway_by,
r.received_at, r.confirmed_at, r.operator, r.remark,
r.version, r.created_at, r.updated_at
FROM purchase_receipt r
WHERE r.deleted = FALSE

    AND r.receipt_no ILIKE CONCAT('%', #{query.receiptNo}, '%')


    AND r.purchase_order_id = #{query.purchaseOrderId}


    AND r.supplier_id = #{query.supplierId}


    AND r.warehouse_id = #{query.warehouseId}


    AND r.status = #{query.status}


    AND r.receipt_mode = #{query.receiptMode}


    AND r.putaway_status = #{query.putawayStatus}


    AND r.received_at >= #{query.receivedFrom}


    AND r.received_at < #{query.receivedTo}

ORDER BY r.created_at DESC, r.id DESC

mapper.update:
UPDATE purchase_receipt
SET deleted    = TRUE,
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{id}
  AND version = #{version}
  AND deleted = FALSE
